package com.example.starter.specimen.model;

/**
 * 分装状态：AVAILABLE 可用；RESERVED 已被检测申请预留；CONSUMED 已消耗；QUARANTINED 已污染隔离。
 */
public enum AliquotStatus {
    AVAILABLE,
    RESERVED,
    CONSUMED,
    QUARANTINED
}

package com.example.starter.specimen.model;

/**
 * 检测申请状态：RESERVED 已预留未开始；CONSUMED 已开始并消耗占用量；CANCELLED 已取消。
 */
public enum AssayStatus {
    RESERVED,
    CONSUMED,
    CANCELLED
}

package com.example.starter.specimen.model;

/**
 * 可交接保管的实体类型：SPECIMEN 样本；ALIQUOT 分装；ASSAY 检测申请。
 */
public enum EntityType {
    SPECIMEN,
    ALIQUOT,
    ASSAY
}

