package com.example.starter.specimen.model;

import java.math.BigDecimal;
import java.time.Instant;

/**
 * 原始样本行：体积单位微升（三位小数），remainingVolumeUl 与全部分装体积之和精确守恒。
 */
public record SpecimenRow(
        String specimenId,
        BigDecimal totalVolumeUl,
        BigDecimal remainingVolumeUl,
        String custodian,
        long version,
        Instant lastEventAt,
        Instant createdAt) {
}

package com.example.starter.specimen.model;

import java.math.BigDecimal;
import java.time.Instant;

/**
 * 分装行：由分装操作生成，携带状态、当前保管方与乐观锁版本。
 */
public record AliquotRow(
        String aliquotId,
        String specimenId,
        BigDecimal volumeUl,
        AliquotStatus status,
        String custodian,
        long version,
        Instant lastEventAt,
        Instant createdAt) {
}

package com.example.starter.specimen.model;

import java.math.BigDecimal;
import java.time.Instant;

/**
 * 检测申请行：占用指定分装的体积；result 在未出结果或已取消时为 null。
 */
public record AssayRow(
        String assayId,
        String aliquotId,
        String project,
        BigDecimal reservedVolumeUl,
        AssayStatus status,
        String result,
        String custodian,
        long version,
        Instant lastEventAt,
        Instant createdAt) {
}

package com.example.starter.specimen.model;

import java.time.Instant;

/**
 * 保管交接事件行：记录一次保管方变更；requestId 为幂等键，重复交接不新增事件。
 */
public record CustodyEventRow(
        long id,
        EntityType entityType,
        String entityId,
        String fromCustodian,
        String toCustodian,
        Instant eventAt,
        String requestId,
        Instant createdAt) {
}

package com.example.starter.specimen.model;

import java.time.Instant;

/**
 * 幂等记录行：requestId 唯一；fingerprint 识别同键异参；responseBody 为首次响应快照。
 */
public record IdempotencyRecordRow(
        String requestId,
        String operation,
        String fingerprint,
        String responseBody,
        Instant createdAt) {
}

