    void quarantinePreservesConsumedAssayAndCustodyHistory() throws Exception {
        // 同一样本分装两次：aliquot-1 将被消耗，aliquot-2 将被污染隔离
        postJson("/api/specimens", Map.of("specimenId", "SP-1",
